import React, { useState } from 'react';
import './App.css';
import Login from './Login';

function App() {
  const [page, setPage] = useState('accueil');

  if (page === 'login') {
    return <Login />;
  }

  return (
    <div className="app">
      <header className="header">
        <div className="logo">🎵 Varim Music</div>
        <nav className="nav">
          <a href="#">Accueil</a>
          <a href="#">Nouveautés</a>
          <a href="#">Top Ventes</a>
          <a href="#">Genres</a>
        </nav>
        <div className="auth-buttons">
          <button className="btn-login" onClick={() => setPage('login')}>
            Connexion
          </button>
          <button className="btn-register">S'inscrire</button>
        </div>
      </header>

      <main className="hero">
        <h1>La musique africaine<br/>à portée de main</h1>
        <p>Découvrez, écoutez et soutenez les artistes africains</p>
        <button className="btn-explore">Explorer la musique</button>
      </main>
    </div>
  );
}

export default App;
